#!/usr/bin/env bash
# Fetch the annotated datasets used by the experiments and verify them against
# datasets/MANIFEST.sha256 (the checksums of the exact files behind every
# number in the paper).
#
# Provenance. Sequence structure comes from the public SPMF datasets; item
# quantities and unit profits were generated by src/main/java/SPMF_Converter.java
# (seed 42). Three datasets (BIBLE, BMS1, C8T1S5I8N5K) are value-identical to
# release v1.1-seed42-lognormal of the shared dataset repository (only the
# comment line of the _eui file differs); FIFA, KOSARAK, LEVIATHAN and SIGN were
# produced by an earlier batch conversion whose generator was shared across the
# batch and therefore cannot be regenerated from the raw SPMF files with a
# per-file seed, so they are distributed verbatim.
#
# Ta-Feng is the exception to all of the above, and the only database here whose
# utilities are measured rather than generated: its item profits are unit prices
# read from the source transaction log, so nothing about it is seeded. It is
# rebuilt exactly by scripts/build_tafeng.py from the public Ta-Feng file, and a
# rebuild reproduces both files byte for byte.
#
# The files live in the shared dataset repository of the group,
# https://github.com/tran-minh-thai/huspm-datasets, under their own tag
# (hausp-ub-v2-tafeng, which adds Ta-Feng to the sixteen files of the earlier
# hausp-ub-v1-exact and leaves those sixteen untouched; that earlier tag is kept
# so results recorded against it stay traceable). That tag exists because the other releases of that
# repository carry different conversions of the same source sequences: only two
# of the eighteen files match them byte for byte, so they cannot stand in here.
# The manifest below is what decides whether a download is usable.
#
# Usage:
#   ./scripts/fetch_datasets.sh                # download + verify into datasets/
#   ./scripts/fetch_datasets.sh --verify-only  # only check files already present
#
# Override the source with DATASETS_URL=<url of the .tar.gz>.
set -euo pipefail

cd "$(dirname "$0")/.."
TAG="${DATASETS_TAG:-hausp-ub-v2-tafeng}"
REPO="${DATASETS_REPO:-tran-minh-thai/huspm-datasets}"
ASSET="${DATASETS_ASSET:-hausp-ub-datasets-v2-tafeng.tar.gz}"
URL="${DATASETS_URL:-https://github.com/$REPO/releases/download/$TAG/$ASSET}"

if [ "${1:-}" != "--verify-only" ]; then
    echo "[fetch] downloading $URL"
    tmp="$(mktemp -t hausp-datasets.XXXXXX.tar.gz)"
    curl -fL --retry 3 -o "$tmp" "$URL"
    echo "[fetch] extracting into datasets/"
    tar xzf "$tmp" -C datasets
    rm -f "$tmp"
fi

echo "[fetch] verifying against datasets/MANIFEST.sha256"
cd datasets
if command -v shasum >/dev/null 2>&1; then
    shasum -a 256 -c MANIFEST.sha256
else
    sha256sum -c MANIFEST.sha256
fi
echo "[fetch] all files match the manifest"
